CREATE TABLE public.app_settings (key text PRIMARY KEY, value jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.app_settings TO service_role; ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY; CREATE TRIGGER update_app_settings_updated_at BEFORE UPDATE ON public.app_settings FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); CREATE TABLE public.donations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id text NOT NULL, amount numeric(10,2) NOT NULL, status text NOT NULL DEFAULT 'pending', provider text NOT NULL DEFAULT 'mercadopago', provider_payment_id text, qr_code text, qr_code_base64 text, ticket_url text, payer_email text, consumed boolean NOT NULL DEFAULT false, consumed_at timestamptz, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX donations_session_idx ON public.donations (session_id, status); CREATE INDEX donations_provider_payment_idx ON public.donations (provider_payment_id); GRANT ALL ON public.donations TO service_role; ALTER TABLE public.donations ENABLE ROW LEVEL SECURITY; CREATE TRIGGER update_donations_updated_at BEFORE UPDATE ON public.donations FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();